window.__posterData({"id": "clara-tenggren", "name": "Clara Tenggren", "folder": "Week1_Poster_ClaraTenggren", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Bilder\nlet bakgrund;\nlet mane;\nlet glitter;\n\n// Rotation\nlet vinkel = 0;\n\n//AI steg 3: AI la till en variabel för pulsen av den orangea cirkeln\nlet puls = 0;\n\n// Informationstext\nlet texter = [\n  'ONE NIGHT ONLY',\n  'DJs: TBA',\n  'FOLLOW THE MOON',\n  'BRING YOUR OWN LIGHT'\n];\n\n//AI steg 2: frågade om att ändra min loop så att texterna inte hamnar på en rad under varandra. Den skapade variabler för varje ords position X & Y\nlet positioner = [\n  [160, 630],\n  [420, 670],\n  [180, 710],\n  [410, 750]\n];\n\nasync function setup() {\n  bakgrund = await loadImage('bakgrund2.png');\n  mane = await loadImage('pinkmoon2.png');\n  glitter = await loadImage('glitter2.png');\n\n  createCanvas(600, 800);\n}\n\nfunction draw() {\n  image(bakgrund, 0, 0);\n\n  // Kontrollera om användaren klickar nära månen\n  let avstand = dist(mouseX, mouseY, width / 2, height / 2 - 70); // jag la till - 70 så att avståndet nu stämmer överrens med månens placering eftersom AI flyttade upp den men ändrade inte denna funktion\n  let visaGlitter = mouseIsPressed && avstand < 200;\n\n  if (visaGlitter) {\n    image(glitter, 0, 0);\n  }\n\n  // Aktivera glödeffekt\n  drawingContext.shadowBlur = 20;\n  drawingContext.shadowColor = color(255, 63, 226);\n\n  ritaRing();\n  ritaMane();\n  ritaText();\n  ritaHemligText(visaGlitter);\n  ritaNamn();\n\n  // Öka rotationen när användaren klickar nära månen\n  if (visaGlitter) {\n    vinkel += 0.4;\n  }\n}\n\n//AI steg 3\nfunction ritaRing() {\n  puls += 0.05;\n\n  // Ringen pulserar mellan 460 och 500 pixlar\n  let storlek = 480 + sin(puls) * 20;\n\n  push();\n\n  noFill();\n  stroke(255, 102, 0);\n  strokeWeight(4);\n\n  drawingContext.shadowBlur = 35;\n  drawingContext.shadowColor = color(255, 102, 0);\n\n  // Flyttar upp ringen 70 pixlar\n  circle(width / 2, height / 2 - 70, storlek);\n\n  pop();\n}\n\nfunction ritaMane() {\n  vinkel += 0.02;\n\n  push();\n\n  // Flyttar upp månen 70 pixlar\n  translate(width / 2, height / 2 - 70);\n\n  rotate(vinkel);\n  imageMode(CENTER);\n\n  // Gör månen större\n  image(mane, 0, 0, 580, 580);\n\n  pop();\n}\n\n// Rita titel och information\nfunction ritaText() {\n  noStroke();\n  textAlign(CENTER, CENTER);\n  textFont('Impact');\n\n  fill(255, 102, 0);\n  textSize(90);\n  text('LUNA RAVE', width / 2, 50);//Jag ändrade från 90 till 50 för att flytta upp rubriken eftersom den annars hamnade på månen efter AI ändringen\n\n  stroke(0, 0, 0);\n  textFont('Courier New Bold');\n  fill(255, 102, 0);\n  textSize(28);\n\n  //AI steg 3: ändrade min tidigare loop från att texterna stog under varandra till att de blev mer utspridda men fortfarande under månen\n  for (let i = 0; i < texter.length; i++) {\n  text(texter[i], positioner[i][0], positioner[i][1]);\n}\n\n  //Gamla loopen\n  //for (let i = 0; i < texter.length; i++) { text(texter[i], width / 2, 660 + i * 30);}\n}\n\n// Rita den hemliga texten vid klick\nfunction ritaHemligText(visaGlitter) {\n  if (visaGlitter) {\n    fill(0, 0, 0);\n    stroke(255, 63, 226);\n    textSize(28);\n    text('LOCATION: UNKNOWN', width / 2, 150);\n  }\n}\n\n// Rita signaturen\nfunction ritaNamn() {\n  fill(255, 63, 226);\n  textSize(25);\n  textFont('Brush Script MT');\n  text('25clte', 550, 785);\n}\n\n// Efter steg 1: Koden blev sju rader längre trots kortare kommentarer, ser ut som att det är på grund av rad 40-44 där alla objekt ritas ut för att sedan enskilt användas genom function. Även raden där månens rotation ökar har flyttats upp. Men koden fungerar som tidigare! \n// AI steg 2: Jag frågade AI om att ändra min loop så att texterna inte hamnade precis under varandra, vilket den gjorde och jag har kommenterat det i koden\n//AI steg 3: AI egna förslag var att göra så att den orange ringen pulserar, jag tycker att den passar bra med resten av postern eftersom den skapar mer rörelse och förstärker känslan av musik och rave. Jag gillar också att AI valde att utveckla ett element som redan fanns i min  jag valde då att utveckla postern en aning genom att även be AI att öka storleken på månen och ringen samt flytta upp de en aning så att det skulle passa bakgrunden som jag skapat bättre.", "assets": {"pinkmoon2.png": {"mime": "image/webp", "b64": ""}, "bakgrund2.png": {"mime": "image/webp", "b64": ""}, "glitter2.png": {"mime": "image/webp", "b64": ""}}});
